//
// Looks up the name of a tag type (TypeScript: `names[tagType]`), or null when there is none.
//
pub fn lookup(names: []const ITagName, tagType: u16) ?[]const u8 {
    for (names) |entry| {
        if (entry.tagType == tagType) {
            return entry.name;
        }
    }
    return null;
}
